def find_line(inp):
    h,w=len(inp),len(inp[0])
    # full empty rows strictly inside bounding box of nonzero cells
    nz=[(i,j) for i in range(h) for j in range(w) if inp[i][j]]
    if not nz: return None
    r0,r1=min(i for i,_ in nz),max(i for i,_ in nz)
    c0,c1=min(j for _,j in nz),max(j for _,j in nz)
    for i in range(r0+1,r1):
        if all(inp[i][j]==0 for j in range(c0,c1+1)): return ('h',i)
    for j in range(c0+1,c1):
        if all(inp[i][j]==0 for i in range(r0,r1+1)): return ('v',j)
    return None

def transform(g):
    line=find_line(g)
    g=[row[:] for row in g]
    if line:
        k,i=line
        if k=='h': g[i]=[3]*len(g[0])
        else:
            for r in g: r[i]=3
    return g

